using System;using System.IO;using System.Linq;using System.Collections.Generic;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.Runtime;using BHT.Bridge;using BHT.Core;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class Street642Probe {static List<string> log=new List<string>();static void Check(string n,bool ok){log.Add((ok?"PASS ":"FAIL ")+n);}
[CommandMethod("STREET642PROBE")]public void Run(){try{var db=AcApp.DocumentManager.MdiActiveDocument.Database;var template=TdtSignLibrary.EnsureBlock(db,"I.449");Check("native-template-import",template.Ok);foreach(var title in new[]{"Đường Nam Rạch Vọp","Đường Nguyễn Thị Minh Khai nối dài thành phố Hồ Chí Minh","AH112"}){var f=new SignContentFace{Index=0,Code="I.449"};f.Values["NAME#0"]=title;var name=SignContentBlocks.Ensure(db,template.BlockName,"I.449",0,SignContent.Write(new[]{f}));using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var block=(BlockTableRecord)tr.GetObject(bt[name],OpenMode.ForRead);var texts=block.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead) as DBText).Where(t=>t!=null).ToList();Check("one-readable-name-"+title,texts.Count==1 && texts[0].TextString==title && Math.Abs(texts[0].WidthFactor-1)<1e-8);using(var br=new BlockReference(Point3d.Origin,block.ObjectId)){var bounds=br.GeometricExtents;Check("compact-bounds-"+title,bounds.MaxPoint.X-bounds.MinPoint.X<=3.21 && bounds.MaxPoint.Y<=1.251);var b=texts[0].GeometricExtents;Check("name-contained-"+title,b.MinPoint.X>=bounds.MinPoint.X && b.MaxPoint.X<=bounds.MaxPoint.X && b.MinPoint.Y>.6 && b.MaxPoint.Y<1.25);}}Check("cache-stable",name==SignCorrections.StreetName(db,template.BlockName,title));var outline=TdtSignLibrary.EnsureOutlineBlock(db,name);using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var b=(BlockTableRecord)tr.GetObject(bt[outline],OpenMode.ForRead);var text=b.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<DBText>().Single();Check("outline-text-preserved",text.TextString==title && text.WidthFactor==1);using(var br=new BlockReference(Point3d.Origin,b.ObjectId)){br.Rotation=.7;Check("rotated-outline-bounds",br.GeometricExtents.MaxPoint.X>br.GeometricExtents.MinPoint.X);}}}
foreach(var path in new[]{@"C:\Program Files\BZS\ADSCivil NW 2026 For Autocad\Template\Block2D\Coc tieu.dwg",@"C:\Program Files\BZS\ADSCivil NW 2026 For Autocad\PicketParapet\picket.dwg"}){using(var src=new Database(false,true)){src.ReadDwgFile(path,FileOpenMode.OpenForReadAndAllShare,false,"");src.CloseInput(true);using(var tr=src.TransactionManager.StartOpenCloseTransaction()){var bt=(BlockTable)tr.GetObject(src.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);log.Add("SOURCE "+path);foreach(var g in ms.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).GroupBy(o=>o.GetType().Name))log.Add("TYPE "+g.Key+" "+g.Count());}}}
}catch(System.Exception ex){log.Add("FAIL "+ex);}File.WriteAllLines(Path.Combine(Path.GetDirectoryName(typeof(Street642Probe).Assembly.Location),"street642-report.txt"),log);}}
